function Badge({ children }) {
  const v = String(children || "");
  let bg, color;
  if (v === "Active" || v === "Approved" || v === "Yes" || v === "Excellent" || v === "Compliant") {
    bg = "#E1F5EE"; color = "#085041";
  } else if (v === "Pending" || v.includes("Need") || v === "Good" || v === "Very Good") {
    bg = "#FAEEDA"; color = "#633806";
  } else if (v === "Inactive" || v === "Rejected") {
    bg = "#FCEBEB"; color = "#791F1F";
  } else {
    bg = "#F1EFE8"; color = "#444441";
  }
  return (
    <span style={{ background: bg, color, fontSize: 12, fontWeight: 500, padding: "3px 10px", borderRadius: 99, display: "inline-block" }}>
      {children || "—"}
    </span>
  );
}

function Avatar({ initials, size = 44 }) {
  return (
    <div style={{ width: size, height: size, borderRadius: "50%", background: TEAL_LIGHT, color: TEAL, display: "flex", alignItems: "center", justifyContent: "center", fontSize: size * 0.32, fontWeight: 500, flexShrink: 0 }}>
      {initials}
    </div>
  );
}

function FieldGrid({ data, editable }) {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
      {Object.entries(data).map(([label, value]) => (
        <div key={label} style={{ background: "var(--color-background-secondary)", borderRadius: "var(--border-radius-md)", padding: "12px 14px" }}>
          <p style={{ fontSize: 11, color: "var(--color-text-secondary)", textTransform: "uppercase", letterSpacing: "0.05em", margin: 0, marginBottom: 6 }}>{label}</p>
          {editable
            ? <input defaultValue={value} placeholder={label} style={{ width: "100%", fontSize: 13, fontWeight: 500, color: "var(--color-text-primary)", background: "var(--color-background-primary)", border: "0.5px solid var(--color-border-secondary)", borderRadius: "var(--border-radius-md)", padding: "6px 10px" }} />
            : <p style={{ fontSize: 13, fontWeight: 500, color: "var(--color-text-primary)", margin: 0, minHeight: 20 }}>{value || "—"}</p>
          }
        </div>
      ))}
    </div>
  );
}

function CircleScore({ score }) {
  const n = parseFloat(score) || 0;
  const r = 40, cx = 52, cy = 52, stroke = 8;
  const circ = 2 * Math.PI * r;
  const dash = (n / 100) * circ;
  const color = n >= 90 ? TEAL_MID : n >= 75 ? "#BA7517" : "#E24B4A";
  const label = n >= 90 ? "Excellent" : n >= 75 ? "Very Good" : n >= 60 ? "Good" : "Needs Improvement";
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
      <svg width={104} height={104}>
        <circle cx={cx} cy={cy} r={r} fill="none" stroke="var(--color-background-secondary)" strokeWidth={stroke} />
        <circle cx={cx} cy={cy} r={r} fill="none" stroke={color} strokeWidth={stroke} strokeDasharray={`${dash} ${circ}`} strokeLinecap="round" transform={`rotate(-90 ${cx} ${cy})`} />
        <text x={cx} y={cy - 4} textAnchor="middle" fontSize={20} fontWeight={500} fill="var(--color-text-primary)">{Math.round(n)}</text>
        <text x={cx} y={cy + 14} textAnchor="middle" fontSize={11} fill="var(--color-text-secondary)">/100</text>
      </svg>
      <div>
        <p style={{ fontSize: 13, color: "var(--color-text-secondary)", margin: 0 }}>Average Score</p>
        <p style={{ fontSize: 14, fontWeight: 500, color, margin: "4px 0 0" }}>{label} ↗</p>
      </div>
    </div>
  );
}

